import type { APIRoute } from 'astro';
import { getCollection } from 'astro:content';
import { siteConfig } from '../site-config.ts';
import { BlogService } from '../lib/blog-service.ts';
import { ensureTrailingSlash } from '../lib/utils.ts';

export const prerender = true;

export const GET: APIRoute = async () => {
    const canonical = ensureTrailingSlash(siteConfig.site.canonical);
    const lines: string[] = [];

    lines.push(`# ${siteConfig.site.siteName}`);
    lines.push('');
    lines.push(`> ${siteConfig.homePageConfig.seo.description}`);
    lines.push('');
    lines.push('## Páginas');
    lines.push('');
    lines.push(`- [${siteConfig.site.siteName}](${canonical}): ${siteConfig.homePageConfig.seo.description}`);

    if (siteConfig.features?.blog) {
        // Only list articles that also have a routable page: getStaticPaths()
        // in pages/blog/[...slug].astro builds pages from the content collection,
        // not directly from the database, so a published DB row without a
        // matching content/blog/*.md entry never gets a static page.
        const blogEntries = await getCollection('blog');
        const routableSlugs = new Set(blogEntries.map((entry) => entry.slug));

        const articles = await BlogService.getPublishedArticles();
        const routableArticles = articles.filter(
            (article) => article.slug && routableSlugs.has(article.slug)
        );

        if (routableArticles.length > 0) {
            lines.push('');
            lines.push('## Blog');
            lines.push('');

            for (const article of routableArticles) {
                const url = `${canonical}blog/${article.slug}/`;
                const description = article.seo_description || siteConfig.blogPageConfig?.seo?.description || '';
                lines.push(`- [${article.title}](${url})${description ? `: ${description}` : ''}`);
            }
        }
    }

    return new Response(lines.join('\n') + '\n', {
        headers: {
            'Content-Type': 'text/markdown; charset=utf-8',
        },
    });
};
